import{_ as s,o as e,c as n,ag as t}from"./chunks/framework.Cyu1VozZ.js";const u=JSON.parse('{"title":"Self-Hosting","description":"","frontmatter":{},"headers":[],"relativePath":"developers/self-hosting.md","filePath":"developers/self-hosting.md"}'),i={name:"developers/self-hosting.md"};function o(l,a,p,r,c,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="self-hosting" tabindex="-1">Self-Hosting <a class="header-anchor" href="#self-hosting" aria-label="Permalink to &quot;Self-Hosting&quot;">​</a></h1><p>Wafflebase is open source (Apache-2.0) and designed to run on your own infrastructure. Your data stays on your servers.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Minimum</th></tr></thead><tbody><tr><td>Node.js</td><td>18+</td></tr><tr><td>PostgreSQL</td><td>14+</td></tr><tr><td>Docker (optional)</td><td>20+</td></tr></tbody></table><h2 id="quick-start-with-docker-compose" tabindex="-1">Quick Start with Docker Compose <a class="header-anchor" href="#quick-start-with-docker-compose" aria-label="Permalink to &quot;Quick Start with Docker Compose&quot;">​</a></h2><p>The fastest way to run Wafflebase locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/wafflebase/wafflebase.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wafflebase</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Starts PostgreSQL + Yorkie server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Run database migrations</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # Start frontend (:5173) + backend (:3000)</span></span></code></pre></div><p>This starts:</p><ul><li><strong>Frontend</strong> at <code>http://localhost:5173</code></li><li><strong>Backend API</strong> at <code>http://localhost:3000</code></li><li><strong>PostgreSQL</strong> for user accounts and document metadata</li><li><strong>Yorkie server</strong> for real-time CRDT collaboration</li></ul><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><p>Create a <code>.env</code> file in <code>packages/backend/</code>:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Required</span></span>
<span class="line"><span>DATABASE_URL=postgresql://wafflebase:wafflebase@localhost:5432/wafflebase</span></span>
<span class="line"><span>JWT_SECRET=your_secret_here</span></span>
<span class="line"><span>GITHUB_CLIENT_ID=your_github_client_id</span></span>
<span class="line"><span>GITHUB_CLIENT_SECRET=your_github_client_secret</span></span>
<span class="line"><span>GITHUB_CALLBACK_URL=http://localhost:3000/auth/github/callback</span></span>
<span class="line"><span>FRONTEND_URL=http://localhost:5173</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Optional</span></span>
<span class="line"><span>PORT=3000</span></span>
<span class="line"><span>JWT_ACCESS_EXPIRES_IN=1h</span></span>
<span class="line"><span>JWT_REFRESH_EXPIRES_IN=7d</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Optional — S3-compatible blob storage. PDF uploads and embedded images</span></span>
<span class="line"><span># use two separate buckets. In development both default to the MinIO</span></span>
<span class="line"><span># container (localhost:9000); in production every value must be set.</span></span>
<span class="line"><span>FILE_STORAGE_ENDPOINT=http://localhost:9000    # PDF uploads</span></span>
<span class="line"><span>FILE_STORAGE_BUCKET=wafflebase-files</span></span>
<span class="line"><span>FILE_STORAGE_REGION=us-east-1</span></span>
<span class="line"><span>FILE_STORAGE_ACCESS_KEY=minioadmin</span></span>
<span class="line"><span>FILE_STORAGE_SECRET_KEY=minioadmin</span></span>
<span class="line"><span>IMAGE_STORAGE_ENDPOINT=http://localhost:9000   # embedded images</span></span>
<span class="line"><span>IMAGE_STORAGE_BUCKET=wafflebase-images</span></span>
<span class="line"><span>IMAGE_STORAGE_REGION=us-east-1</span></span>
<span class="line"><span>IMAGE_STORAGE_ACCESS_KEY=minioadmin</span></span>
<span class="line"><span>IMAGE_STORAGE_SECRET_KEY=minioadmin</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Optional — Share Link view analytics (Kafka + StarRocks). Leave all</span></span>
<span class="line"><span># three unset to disable analytics entirely; the app is unaffected and the</span></span>
<span class="line"><span># dashboard shows &quot;not enabled&quot;. Uncomment and fill in only after starting</span></span>
<span class="line"><span># the \`analytics\` Docker Compose profile (see &quot;Analytics&quot; below) — pointing</span></span>
<span class="line"><span># these at brokers that aren&#39;t running just produces connection errors.</span></span>
<span class="line"><span># WAFFLEBASE_KAFKA_ADDRESSES=localhost:29092</span></span>
<span class="line"><span># WAFFLEBASE_KAFKA_TOPIC=wafflebase-view-events</span></span>
<span class="line"><span># WAFFLEBASE_STARROCKS_DSN=root:@tcp(localhost:9030)/wafflebase</span></span></code></pre></div><h3 id="pdf-image-storage" tabindex="-1">PDF &amp; Image Storage <a class="header-anchor" href="#pdf-image-storage" aria-label="Permalink to &quot;PDF &amp; Image Storage&quot;">​</a></h3><p>Uploaded PDFs and embedded images are stored as blobs in an S3-compatible object store (MinIO in development, any S3 provider in production) rather than in Yorkie. They use <strong>two separate buckets</strong> with their own settings:</p><ul><li><strong><code>FILE_STORAGE_*</code></strong> — PDF uploads (default bucket <code>wafflebase-files</code>)</li><li><strong><code>IMAGE_STORAGE_*</code></strong> — embedded images (default bucket <code>wafflebase-images</code>)</li></ul><p>In production every value must be set explicitly. If <code>FILE_STORAGE_*</code> is missing, PDF upload is unavailable; if <code>IMAGE_STORAGE_*</code> is missing, image insertion is unavailable — in each case the rest of the app runs normally.</p><h3 id="analytics-optional" tabindex="-1">Analytics (optional) <a class="header-anchor" href="#analytics-optional" aria-label="Permalink to &quot;Analytics (optional)&quot;">​</a></h3><p>Wafflebase can record <strong>Share Link view analytics</strong> — views, unique/returning visitors, dwell time, and a per-link breakdown — surfaced on a per-document and per-workspace dashboard. This is entirely optional and <strong>off by default</strong>: with the three <code>WAFFLEBASE_KAFKA_*</code> / <code>WAFFLEBASE_STARROCKS_DSN</code> variables unset, the whole pipeline is a no-op and the dashboard shows &quot;not enabled&quot;. The rest of the app is unaffected.</p><p>The pipeline reuses the same stack Yorkie ships for its own analytics:</p><ul><li><strong>Kafka</strong> — the backend batches client view events (via a <code>sendBeacon</code> endpoint) onto a Kafka topic.</li><li><strong>StarRocks</strong> — a Routine Load ingests the topic into a <code>wafflebase.view_events</code> table; the dashboard queries it back over MySQL wire protocol.</li></ul><p>Both run as an <strong>opt-in Docker Compose profile</strong> kept out of the default stack:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analytics</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # + the default postgres/yorkie/minio</span></span></code></pre></div><p>Then point the backend at them with the analytics variables shown above (<code>WAFFLEBASE_KAFKA_ADDRESSES=localhost:29092</code>, <code>WAFFLEBASE_KAFKA_TOPIC=wafflebase-view-events</code>, <code>WAFFLEBASE_STARROCKS_DSN=root:@tcp(localhost:9030)/wafflebase</code>). Open a document through a share link to emit events, then visit the workspace <strong>Analytics</strong> tab.</p><h3 id="github-oauth-setup" tabindex="-1">GitHub OAuth Setup <a class="header-anchor" href="#github-oauth-setup" aria-label="Permalink to &quot;GitHub OAuth Setup&quot;">​</a></h3><ol><li>Go to <a href="https://github.com/settings/developers" target="_blank" rel="noreferrer">GitHub Developer Settings</a></li><li>Click <strong>New OAuth App</strong></li><li>Set the <strong>Authorization callback URL</strong> to <code>http://your-domain:3000/auth/github/callback</code></li><li>Copy the Client ID and Client Secret into your <code>.env</code> file</li></ol><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser ──── Frontend (React/Vite) ──── Backend (NestJS)</span></span>
<span class="line"><span>                                              │</span></span>
<span class="line"><span>                                        ┌─────┴─────┐</span></span>
<span class="line"><span>                                   PostgreSQL    Yorkie Server</span></span>
<span class="line"><span>                                   (metadata)    (CRDT sync)</span></span></code></pre></div><ul><li><strong>PostgreSQL</strong> stores user accounts, document metadata, share links, and API keys</li><li><strong>Yorkie</strong> handles real-time document synchronization between clients using CRDTs</li><li><strong>Backend</strong> manages authentication, authorization, and REST API</li><li><strong>Frontend</strong> renders the spreadsheet UI and connects to Yorkie for live collaboration</li></ul><h2 id="data-ownership" tabindex="-1">Data Ownership <a class="header-anchor" href="#data-ownership" aria-label="Permalink to &quot;Data Ownership&quot;">​</a></h2><p>All your data is stored in:</p><ul><li><strong>PostgreSQL</strong> — User profiles, document records, API keys</li><li><strong>Yorkie</strong> — Editable document content (cells, text, slides, notes, comments)</li><li><strong>Blob storage</strong> — Uploaded PDFs and embedded images (S3-compatible)</li></ul><p>You control all of these services. There are no external dependencies, and no telemetry is sent anywhere outside your own infrastructure. (The optional analytics pipeline above records Share Link view events, but only into the Kafka + StarRocks services you run yourself — and only when you enable it.) Back up your PostgreSQL database, Yorkie data directory, and blob store to preserve everything.</p>`,32)])])}const k=s(i,[["render",o]]);export{u as __pageData,k as default};
